custom_css:
/* === 爱与线 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影. === */

/* --- 1. 字体引入 --- */
@import url('https://fonts.googleapis.com/css2?family=Caveat:wght@400..700&display=swap');
@import url("https://fontsapi.zeoseven.com/440/main/result.css");
@import url("https://fontsapi.zeoseven.com/45/main/result.css");
@import url("https://fontsapi.zeoseven.com/249/main/result.css");
@import url("https://fontsapi.zeoseven.com/223/main/result.css");

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg-color: #FFF5F5;
    --theme-bg-mid: #FEECEE; 
    --card-bg: rgba(255, 255, 255, 0.95);
    --accent-main: #D32F2F; 
    --accent-dark: #8E0000; 
    --accent-light: #FFCDD2; 
    --text-main: #4A1515; 
    --text-subtle: #7F4F4F; 

    --font-english-script: 'Caveat', cursive;
    --font-english-serif: 'Caveat', cursive;
    --font-main: "Huiwen-Fangsong", var(--font-english-serif), sans-serif;
    --font-quote: "Long Cang", var(--font-english-script), serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "huangkaihuaLawyerfont", var(--font-english-script), sans-serif;
}

/* --- 3. 全局样式：无阴影、无边框 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: repeating-linear-gradient(45deg, rgba(211, 47, 47, 0.03) 0px, rgba(211, 47, 47, 0.03) 2px, transparent 2px, transparent 15px) !important; 
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-main); font-weight: normal; }

/* --- 4. 顶部导航栏 & 抽屉背景 (贴图替换) --- */
#top-settings-holder { position:relative; background-color: rgba(255, 255, 255, 0.7); backdrop-filter: blur(10px); border: none !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); }
.drawer-icon.fa-fw:hover { transform: translateY(-3px) scale(1.1) rotate(5deg); }

.drawer-icon.fa-sliders, .drawer-icon.fa-plug, .drawer-icon.fa-font, .drawer-icon.fa-book-atlas, .drawer-icon.fa-user, .drawer-icon.fa-image, .drawer-icon.fa-cubes, .drawer-icon.fa-bars-progress, .drawer-icon.fa-face-smile, .drawer-icon.fa-address-card, #ai-config-button .drawer-icon, #advanced-formatting-button .drawer-icon, #user-settings-button .drawer-icon, #extensions-settings-button .drawer-icon, #persona-management-button .drawer-icon, #sys-settings-button .drawer-icon, #WI-SP-button .drawer-icon, #table_database_settings_drawer .drawer-icon, #character_popup_button .drawer-icon, .drawer-icon.fa-panorama {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260506/3QAC/1638X1640/2026-04-25%2520183334.png/webp') !important; 
}

.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(255, 250, 250, 0.85), rgba(255, 250, 250, 0.95)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260506/zDKE/1200X800/1eea3355a1d438a8fe3f60e107fabbd7.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 8px !important; color: var(--text-main) !important;
}

/* --- 5. 底部悬浮输入栏 --- */
#form_sheld { position: absolute !important; bottom: 10px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { width: 90% !important; max-width: 800px !important; pointer-events: auto; }

#send_form, body.no-blur #send_form { 
    border-radius: 25px !important; 
    background-color: rgba(255, 255, 255, 0.8) !important; 
    padding: 10px 15px !important; 
    backdrop-filter: blur(10px) !important; 
    -webkit-backdrop-filter: blur(10px) !important; 
    border: none !important; 
    box-shadow: none !important; 
    transition: all 0.3s ease !important; 
}
#send_form:hover, body.no-blur #send_form:hover { transform: translateY(-5px); background-color: rgba(255, 255, 255, 0.95) !important; }

#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; font-size: 1.1rem !important; box-shadow: none !important; font-family: var(--font-english-serif); }

#nonQRFormItems { position: relative; }
#send_textarea::placeholder { color: transparent !important; text-shadow: none !important; }

/* 伪提示词 (纯文本字符替换 Emoji) */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: '~ Tying my feelings into the red ribbon ~ + x +'; 
    color: var(--accent-main); 
    position: absolute; 
    top: 50%; transform: translateY(-50%); 
    left: 50px; right: 70px; 
    text-align: center; 
    font-family: var(--font-english-script); 
    font-size: clamp(1rem, 2.5vw, 1.4rem); 
    pointer-events: none; 
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    opacity: 0.7; 
    animation: pulse-ribbon 2s infinite alternate;
}
@keyframes pulse-ribbon { 0% { transform: translateY(-50%) scale(1); opacity: 0.6; } 100% { transform: translateY(-50%) scale(1.02); opacity: 0.9; text-shadow: 0 0 5px rgba(211,47,47,0.3); } }

/* 底栏贴图 */
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before, #mes_impersonate::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button, #mes_impersonate { 
    width: 36px; height: 36px; 
    background-size: contain; background-repeat: no-repeat; background-position: center; 
    transition: transform 0.2s ease; font-size: 0; border: none; background-color: transparent; 
}
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover, #mes_impersonate:hover { transform: scale(1.15) rotate(10deg); }

#options_button, #ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260506/MsSl/2081X1611/2026-05-06%2520103048.png/webp') !important; }
#send_form #extensionsMenuButton, #auto_completion_button, #mes_impersonate { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260506/MZbm/1651X1518/2026-05-06%2520103022.png/webp') !important; }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260506/BuVH/2530X1904/2026-05-06%2520103000.png/webp') !important; }

/* --- 6. 核心：消息框 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 140px auto 60px !important; 
    width: 90%; max-width: 800px; 
    background-color: transparent !important;
}

/* --- 消息框顶部背景图 --- */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; 
    height: 400px !important; 
    min-height: 400px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-radius: 8px;
    border: none !important; 
    background-color: transparent !important; 
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260506/KWF5/4578X2298/2026-05-06%2520171641.png/webp') !important; }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260506/KHnn/4578X2298/2026-05-06%2520171720.png/webp') !important; }

/* 顶端纯文本装饰 */
.mes .mesAvatarWrapper::before {
    content: '+ - - - x - - - +'; 
    position: absolute; top: -15px; left: 50%; transform: translateX(-50%);
    font-size: 16px; font-weight: bold; color: var(--accent-main); letter-spacing: 2px;
    z-index: 40; font-family: var(--font-code);
}

/* --- 放大的头像框 --- */
.mes .avatar {
    position: absolute;
    top: 50%; 
    width: 200px !important; height: 260px !important; 
    background: #FFF !important; 
    padding: 14px 14px 55px 14px !important; 
    z-index: 30; display: flex !important; align-items: flex-start; justify-content: center;
    border-radius: 4px !important; 
    border: none !important;
}
.mes[is_user="false"] .avatar { left: 20px; transform: translateY(-50%) rotate(-4deg); }

/* ✨ 用户头像向左移动 ✨ */
.mes[is_user="true"] .avatar { right: 50px; left: auto; transform: translateY(-50%) rotate(4deg); }

.mes .avatar img { 
    width: 100% !important; height: 100% !important; 
    object-fit: cover !important; border-radius: 2px !important; 
}

/* 胶带装饰 */
.mes .avatar::before {
    content: ''; position: absolute; top: -14px; left: 50%; transform: translateX(-50%) rotate(3deg);
    width: 65px; height: 30px; background-color: rgba(211, 47, 47, 0.2);
    border: none !important; z-index: 40; backdrop-filter: blur(2px);
}
.mes .avatar::after {
    content: '+ LOVE BOUND + \A ~ tied ~'; white-space: pre; position: absolute;
    bottom: 12px; left: 0; right: 0; text-align: center;
    font-family: var(--font-english-script); font-size: 16px; color: var(--accent-main); line-height: 1.2; letter-spacing: 1px;
}

/* --- 悬挂的水洗标：楼层、时间戳、Token数 --- */
.mes .mesIDDisplay, .mes .mes_timer, .mes .tokenCounterDisplay {
    position: absolute !important; 
    bottom: -24px !important; /* 悬挂在正文框体下方 */
    top: auto !important; 
    background-color: var(--card-bg) !important; 
    padding: 6px 14px !important;
    color: var(--accent-main) !important; 
    font-size: 13px !important; 
    font-family: var(--font-code) !important; 
    letter-spacing: 1px !important; 
    white-space: nowrap; 
    z-index: 5 !important;
    border: none !important;
    border-top: 2px dashed rgba(211, 47, 47, 0.4) !important; /* 模拟缝在正文下方的线迹 */
    border-radius: 0 0 6px 6px !important;
}

/* 楼层标签靠左挂 */
.mes .mesIDDisplay {
    left: 45px !important;
    transform: rotate(-2deg) !important;
    transform-origin: top left;
}
/* 时间标签靠右挂 */
.mes .mes_timer {
    right: 45px !important;
    left: auto !important;
    transform: rotate(2deg) !important;
    transform-origin: top right;
}
/* ✨ Token标签挂在正中间 ✨ */
.mes .tokenCounterDisplay {
    left: 50% !important;
    transform: translateX(-50%) !important; /* 居中对齐 */
    color: var(--text-subtle) !important; /* 颜色稍微淡一点以作区分 */
}
/* 添加自定义前缀文字 */
.mesIDDisplay::before { content: 'Thread. '; }
.mes .tokenCounterDisplay::before { content: 'Ties: '; }


/* ========================================================
   电脑端专属微调
======================================================== */
@media (min-width: 800px) {
    .mes[is_user="false"] .avatar { left: 90px !important; }

    /* ✨ 电脑端用户头像进一步向左移动 ✨ */
    .mes[is_user="true"] .avatar { right: 160px !important; }
    /* ✨ 配合头像移动，调整用户名字的边距 ✨ */
    .mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { margin-right: 80px !important; }
}

/* --- 消息正文与布料缝合效果 (重构底纹) --- */
.mes .mes_block { 
    margin-top: 50px !important; 
    background-color: var(--card-bg) !important; 
    padding: 40px 40px 50px 60px !important; 
    position: relative; border: none !important; border-radius: 8px;
    min-height: 120px !important; z-index: 10; 
    /* 新底纹：斜向交织的布料纺织纹理 */
    background-image: 
        repeating-linear-gradient(45deg, rgba(211, 47, 47, 0.02) 0px, rgba(211, 47, 47, 0.02) 1px, transparent 1px, transparent 5px),
        repeating-linear-gradient(-45deg, rgba(211, 47, 47, 0.02) 0px, rgba(211, 47, 47, 0.02) 1px, transparent 1px, transparent 5px) !important;
}

/* 模拟布料边缘的缝合线 */
.mes .mes_block::before {
    content: ''; position: absolute; top: 8px; bottom: 8px; left: 8px; right: 8px;
    border: 2px dashed rgba(211, 47, 47, 0.4); border-radius: 6px;
    pointer-events: none; z-index: 1;
}

.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; position: relative; z-index: 10 !important; }

/* 背景隐约的英文装饰涂鸦 */
.mes_block .mes_text::after {
    content: 'Bound by the Red Thread \A Forever Tied'; white-space: pre;
    position: absolute; bottom: 10px; color: rgba(211, 47, 47, 0.05);
    font-family: var(--font-english-script); font-size: 40px; text-align: center; font-weight: bold; transform: rotate(-5deg);
    z-index: 0; pointer-events: none; user-select: none;
}
.mes[is_user="false"] .mes_block .mes_text::after { right: 20px; }
.mes[is_user="true"] .mes_block .mes_text::after { left: 20px; }

/* 思维链自定义 */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; padding: 0 !important; margin-bottom: 15px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "+ Weaving the red threads... (Thinking) +"; 
    font-family: var(--font-english-script); font-size: 24px !important; 
    color: var(--accent-main); visibility: visible; letter-spacing: 1px; 
}
.mes_reasoning { padding-left: 20px !important; margin-bottom: 30px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 1.05em; position: relative; }
.mes_reasoning::before { 
    content: ''; position: absolute; left: 0; top: 5px; bottom: 5px; width: 4px; 
    background: repeating-linear-gradient(45deg, var(--accent-main), var(--accent-main) 4px, transparent 4px, transparent 8px);
}
.mes .mes_text { line-height: 2.2; color: var(--text-main); font-size: 16px; text-align: justify; letter-spacing: 0.5px; }

/* 打字指示器 */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260506/BuVH/2530X1904/2026-05-06%2520103000.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: pulse-ribbon 1s infinite alternate; border: none !important; height: 50px !important; width: 50px !important; margin: 15px auto !important; }
#typing_indicator .dot { display: none !important; }

/* --- 悬浮按钮 --- */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; opacity: 0; transition: opacity 0.4s ease; pointer-events: auto !important; margin-top: 15px; position: relative; z-index: 15; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: rgba(255, 255, 255, 0.9) !important; color: var(--accent-main) !important; padding: 6px !important; border-radius: 4px !important; cursor: pointer; transition: all 0.3s ease; font-size: 14px !important; border: none !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-main) !important; color: #fff !important; transform: scale(1.1) rotate(5deg); }

/* --- 全局UI设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: rgba(255, 255, 255, 0.8) !important; border-radius: 4px !important; padding: 12px 18px !important; margin-bottom: 10px !important; color: var(--text-main) !important; border: none !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: rgba(255,255,255,0.9) !important; color: var(--text-main) !important; border-radius: 4px !important; padding: 10px !important; border: none !important; font-family: var(--font-english-serif); }
input:focus, textarea:focus, select:focus { outline: none !important; background-color: #fff !important; }
.menu_button { background-color: rgba(255, 255, 255, 0.8) !important; color: var(--accent-main) !important; transition: all 0.3s ease; border-radius: 4px !important; border: none !important; }
.menu_button:hover, .menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-main) !important; color: white !important; transform: translateY(-2px); }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-main) !important; }

dialog.popup { background-color: transparent !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(255, 255, 255, 0.95); z-index: 0; border-radius: 8px; border: none !important; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }

#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { background-color: rgba(255,255,255,0.9) !important; color: var(--accent-main) !important; border-radius: 4px !important; padding: 12px 24px !important; margin: 10px 8px !important; transition: all 0.3s ease !important; border: none !important; }
#dialogue_del_mes_ok:hover { background-color: var(--accent-main) !important; color: #fff !important; transform: translateY(-2px) rotate(-2deg) !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--text-subtle) !important; color: #fff !important; transform: translateY(-2px) rotate(2deg) !important; }

/* --- 手机端适配调整 --- */
@media (max-width: 768px) {
    .mes { margin: 120px auto 40px !important; }
    .mes .mesAvatarWrapper { height: 250px !important; min-height: 250px !important; margin-bottom: 30px; }
    .mes > .ch_name, .mes .mes_block > .ch_name { bottom: 10px !important; padding: 6px 14px !important; }

    .mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { left: 170px !important; }
    .mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { right: 170px !important; }
    .mes .ch_name .name_text { font-size: 18px !important; }

    .mes .avatar { width: 140px !important; height: 190px !important; padding: 10px 10px 45px 10px !important; }
    .mes .avatar::after { font-size: 10px; bottom: 8px; }

    .mes .mes_block { 
        padding: 30px 20px 40px 20px !important; 
        margin-top: 30px !important; 
    }

    /* 手机端水洗标位置适配 */
    .mes .mesIDDisplay { left: 20px !important; }
    .mes .mes_timer { right: 20px !important; }
}

/* --- 名字卡片 --- */
.mes > .ch_name, .mes .mes_block > .ch_name { 
    display: flex !important; 
    position: relative !important; 
    top: auto !important;
    bottom: auto !important; 
    transform: none !important; 

    background: #FFFFFF !important;
    border: 1px dashed rgba(211, 47, 47, 0.4) !important; /* 加了一点虚线边框，使其像布贴 */
    border-bottom: none !important;
    border-radius: 8px 8px 0 0 !important; 

    margin-bottom: -5px !important; 
    z-index: 20 !important; 

    padding: 6px 16px 8px 16px !important; 
    align-items: center !important; 
    gap: 12px !important;

    width: fit-content !important; 
    max-width: 85% !important; 
    white-space: normal !important; 
    word-break: break-word !important; 
}

.mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { 
    left: auto !important; 
    right: auto !important; 
    align-self: flex-start !important; 
    margin-left: 10px !important; 
}

.mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { 
    left: auto !important; 
    right: auto !important; 
    align-self: flex-end !important; 
    margin-right: 20px !important; 
}

.mes .ch_name .name_text { 
    font-family: var(--font-english-script); 
    font-size: 20px !important; 
    letter-spacing: 1px; 
    color: var(--accent-main) !important; 
    text-transform: capitalize; 
}

